<?php
declare(strict_types=1);
namespace App\Infrastructure\Cache;
use App\Domain\Generations\Generation;use App\Domain\Generations\GenerationId;use App\Domain\Generations\GenerationRepository;
final class CachedGenerationRepository implements GenerationRepository { public function __construct(private GenerationRepository $inner, private RedisCache $cache, private int $ttlSeconds = 300) {} public function nextId(): GenerationId { return $this->inner->nextId(); } public function save(Generation $generation): void { $this->inner->save($generation); $this->cache->del('generation:id:'.$generation->id()->value()); } public function listByUser(string $userId): array { return $this->inner->listByUser($userId); } public function byId(GenerationId $id): ?Generation { $key='generation:id:'.$id->value(); $cached=$this->cache->get($key); if($cached!==null){$d=json_decode($cached,true,512,JSON_THROW_ON_ERROR); return Generation::reconstitute(GenerationId::fromString($d['id']),$d['userId'],$d['type'] ?? 'lesson_plan',$d['subject'],$d['topic'],$d['details'],$d['grade'],(int)$d['duration'],$d['lang'],$d['prompt'],$d['status'],$d['resultMd'],$d['resultJson'],new \DateTimeImmutable($d['createdAt']),new \DateTimeImmutable($d['updatedAt']));} $g=$this->inner->byId($id); if($g!==null){$this->cache->set($key,json_encode(['id'=>$g->id()->value(),'userId'=>$g->userId(),'type'=>$g->type(),'subject'=>$g->subject(),'topic'=>$g->topic(),'details'=>$g->details(),'grade'=>$g->grade(),'duration'=>$g->duration(),'lang'=>$g->lang(),'prompt'=>$g->prompt(),'status'=>$g->status(),'resultMd'=>$g->resultMd(),'resultJson'=>$g->resultJson(),'createdAt'=>$g->createdAt()->format(DATE_ATOM),'updatedAt'=>$g->updatedAt()->format(DATE_ATOM)],JSON_THROW_ON_ERROR),$this->ttlSeconds);} return $g; } public function delete(GenerationId $id): void { $this->inner->delete($id); $this->cache->del('generation:id:'.$id->value()); }}
